static const char *ratr_lookup(const char *s, int l)
{
    if (!lang_ok(l)) return 0;
    for (unsigned i = 0; i < sizeof RATR / sizeof RATR[0]; i++) if (!strcmp(RATR[i][0], s)) return RATR[i][1 + l];
    return 0;
}
